        "intro": "Türkçe fiil mastarları '-mak' veya '-mek' ile biter: yapmak (فعل / to do), gitmek (ذهاب / to go). Türkçe cümle yapısı Özne-Nesne-Yüklem (SOV) sırasındadır. Yüklem (fiil) cümlenin sonunda yer alır. (English: Turkish infinitives end in -mak or -mek. The sentence structure is Subject-Object-Verb, so the verb is always at the end.)",
